      "style": "normal",
      "children": [
       {
        "_type": "span",
        "text": "A female raccoon may use an attic, chimney, crawlspace or other protected area as a den. If dependent young are present, simply removing or excluding the adult can create additional problems.",
        "marks": []
       }
      ],
