       "_type": "span",
       "text": "Snake in your house, garage, pool, yard or business? Finding a snake close to your family, pets or customers can be alarming, especially when you cannot confidently identify the species. Pro Wildlife Removal provides professional snake identification, removal and property inspection throughout Tampa and West-Central Florida. Most Florida snakes are non-venomous, but several venomous species occur in the state. If you cannot confidently identify a snake, keep your distance, keep children and pets away and avoid handling it yourself.",
