        "_type": "span",
        "text": "We highly recommend that you do not attempt to remove or destroy a bee’s nest on your own. This can be extremely dangerous to you and others around you. When threatened, bees will attack with their stingers. When a bee stings you, they release pheromones that tell the other bees to attack as well. This signals a swarming, stinging frenzy, which can quickly become a dangerous situation. Call our Bee removal experts for all your bee removal needs ",
