      "level": 1,
      "markDefs": [],
      "children": [
       {
        "_type": "span",
        "text": "Stay calm. If you panic, they’ll panic. Bees are disturbed by loud sounds and aggressive movements. The last thing you want to do is start screaming and making fast movements. Stay calm and try not to disturb the bees.",
        "marks": []
       }
      ]
